-- mesh.lua
-- Generated by eilmer-mesher. Edit the .emesh.json project, not this file.
--   lmr prep-grids -j mesh.lua      registers the grids for a simulation
--   lmr custom-script -j mesh.lua   writes preview/blk-NNNN.vtk for the GUI
if config then config.dimensions = 2 end

-- points
p000 = Vector3:new{x=0.0, y=0.3}
p001 = Vector3:new{x=0.4, y=0.5}
p002 = Vector3:new{x=1.0, y=0.6}
p003 = Vector3:new{x=1.0, y=0.0}
p004 = Vector3:new{x=1.0, y=1.0}
p005 = Vector3:new{x=0.0, y=0.0}
p006 = Vector3:new{x=0.0, y=1.0}

-- paths
path_c5 = Spline:new{points={p000, p001, p002}}
path_c2 = Line:new{p0=p003, p1=p004}
path_c1 = Line:new{p0=p005, p1=p003}
path_c4 = Line:new{p0=p006, p1=p005}
path_c3 = Line:new{p0=p004, p1=p006}

-- blocks
blocks = {}
-- block blk1
surf_blk1 = CoonsPatch:new{north=path_c5, east=SubRangedPath:new{underlying_path=path_c2, t0=0.0, t1=0.6}, south=path_c1, west=SubRangedPath:new{underlying_path=path_c4, t0=1.0, t1=0.7}}
grid_blk1 = StructuredGrid:new{psurface=surf_blk1, niv=16, njv=7, label="blk1"}
blocks[#blocks+1] = {grid=grid_blk1, tag="blk1", fsTag="initial", bcTags={}}

-- block blk2
surf_blk2 = CoonsPatch:new{north=ReversedPath:new{underlying_path=path_c3}, east=SubRangedPath:new{underlying_path=path_c2, t0=0.6, t1=1.0}, south=path_c5, west=SubRangedPath:new{underlying_path=path_c4, t0=0.7, t1=0.0}}
grid_blk2 = StructuredGrid:new{psurface=surf_blk2, niv=16, njv=9, label="blk2"}
blocks[#blocks+1] = {grid=grid_blk2, tag="blk2", fsTag="initial", bcTags={}}

if registerFluidGrid then
   -- lmr prep-grids
   local ids = {}
   for i, b in ipairs(blocks) do
      ids[i] = registerFluidGrid{grid=b.grid, tag=b.tag, fsTag=b.fsTag, bcTags=b.bcTags}
   end
   -- Blocks are joined only across block split lines; a solid curve between
   -- two blocks stays a wall on both sides.
   connectGrids(ids[1], "north", ids[2], "south")
else
   -- lmr custom-script: preview output for the GUI
   os.execute("mkdir -p preview")
   for i, b in ipairs(blocks) do
      b.grid:write_to_vtk_file(string.format("preview/blk-%04d.vtk", i-1))
   end
end
